<?php
namespace App\Modules\Workflows\Domain\Entities;
use DateTimeImmutable;
final class WorkflowExecution
{
 public function __construct(private string $id,private string $workflowId,private int $workflowVersion,private string $partnerId,private string $contactId,private string $triggerEventId,private string $currentNodeId,private string $status,private array $nodesSnapshot,private array $completedNodes=[],private ?DateTimeImmutable $resumeAt=null,private ?string $failureReason=null,private DateTimeImmutable $createdAt=new DateTimeImmutable(),private ?DateTimeImmutable $updatedAt=null){}
 public function getId():string{return $this->id;}public function getWorkflowId():string{return $this->workflowId;}public function getWorkflowVersion():int{return $this->workflowVersion;}public function getPartnerId():string{return $this->partnerId;}public function getContactId():string{return $this->contactId;}public function getTriggerEventId():string{return $this->triggerEventId;}public function getCurrentNodeId():string{return $this->currentNodeId;}public function getStatus():string{return $this->status;}public function getNodesSnapshot():array{return $this->nodesSnapshot;}public function getCompletedNodes():array{return $this->completedNodes;}public function getResumeAt():?DateTimeImmutable{return $this->resumeAt;}public function getFailureReason():?string{return $this->failureReason;}public function getCreatedAt():DateTimeImmutable{return $this->createdAt;}public function getUpdatedAt():?DateTimeImmutable{return $this->updatedAt;}
 public function getCurrentNodeDef():?array{return $this->currentNodeId===''?null:($this->nodesSnapshot[$this->currentNodeId]??null);}public function isNodeCompleted(string $id):bool{return in_array($id,$this->completedNodes,true);}public function markNodeAsCompleted(string $id):void{if(!$this->isNodeCompleted($id))$this->completedNodes[]=$id;$this->updatedAt=new DateTimeImmutable();}
 public function advance(?string $next):void{if($next===null||$next===''){$this->complete();return;}$this->currentNodeId=$next;$this->status='RUNNING';$this->resumeAt=null;$this->updatedAt=new DateTimeImmutable();}
 public function pauseAt(string $next,DateTimeImmutable $resume):void{$this->currentNodeId=$next;$this->status='PAUSED';$this->resumeAt=$resume;$this->updatedAt=new DateTimeImmutable();}
 public function resume():void{if($this->status==='PAUSED'){$this->status='RUNNING';$this->resumeAt=null;$this->updatedAt=new DateTimeImmutable();}}
 public function complete():void{$this->status='COMPLETED';$this->resumeAt=null;$this->updatedAt=new DateTimeImmutable();}public function cancel():void{$this->status='CANCELED';$this->resumeAt=null;$this->updatedAt=new DateTimeImmutable();}public function fail(string $reason):void{$this->status='FAILED';$this->failureReason=$reason;$this->updatedAt=new DateTimeImmutable();}
}
